mapper.select:
/* AlarmMapper.selectUnconfirmedAlarmCount 수신자의 확인하지 않은 알람 건수를 조회 */
SELECT COUNT(*)
FROM TB_ALRM_L
WHERE RCVR_ID = #{rcvrId}
  AND CFM_YN = 'N'

/* AlarmMapper.selectExistingUsrIdList 사용자 테이블에 있는 사용자ID만 조회 (알람 수신자 검증) */
SELECT USR_ID
FROM TB_USR_M
WHERE USR_ID IN

    #{usrId}

mapper.insert:
/* AlarmMapper.insertAlarm 알람을 등록 */
INSERT INTO TB_ALRM_L (
    ALRM_SN, RCVR_ID, ALRM_TYPE_CD, ALRM_TITL_NM, ALRM_CONT, PRGM_ID, CFM_YN,
    FIRS_REGR_ID, FIRS_REG_DT, FINA_REGR_ID, FINA_REG_DT
) VALUES (
    #{alrmSn}, #{rcvrId}, #{item.alrmTypeCd}, #{item.alrmTitlNm}, #{item.alrmCont}, #{item.prgmId}, 'N',
    #{usrId}, #{regDt}, #{usrId}, #{regDt}
)

mapper.update:
/* AlarmMapper.updateAlarmConfirm 수신자의 미확인 알람을 확인 처리 (알람일련번호가 없으면 전체) */
UPDATE TB_ALRM_L
   SET CFM_YN       = 'Y',
       CFM_DTTM     = CURRENT_TIMESTAMP,
       FINA_REGR_ID = #{rcvrId},
       FINA_REG_DT  = CURRENT_TIMESTAMP
 WHERE RCVR_ID = #{rcvrId}
   AND CFM_YN  = 'N'

   AND ALRM_SN = #{alrmSn}
